test_blocks:
test "t0" {
    assert (normalize_color_tuple(360, 20, 100) == (1, 0.2, 1));;
}

test "t1" {
    assert (normalize_color_tuple(0, 100, 0) == (0, 1, 0));;
}

test "t2" {
    assert (normalize_color_tuple(180, 100, 0) == (0.5, 1, 0));;
}

test "t3" {
    assert (normalize_color_tuple(0, 100, 100) == (0, 1, 1));;
}

test "t4" {
    assert (normalize_color_tuple(10, 20, 30) == ((10 / 360), (20 / 100), (30 / 100)));;
}

test "t5" {
    assert (normalize_color_tuple(180, 100, 90) == (0.5, 1, 0.9));;
}

test "t6" {
    assert (normalize_color_tuple(0, 0, 50) == (0.0, 0.0, 0.5));;
}

test "t7" {
    assert (normalize_color_tuple(0, 50, 50) == (0, 0.5, 0.5));;
}

test "t8" {
    assert (normalize_color_tuple(360, 100, 0) == (1, 1, 0));;
}

test "t9" {
    assert (normalize_color_tuple(180, 100, 100) == (0.5, 1, 1));;
}

test "t10" {
    assert (normalize_color_tuple(1, 2, 3) == ((1 / 360), (2 / 100), (3 / 100)));;
}

test "t11" {
    assert (normalize_color_tuple(0, 50, 50) == (0, 0.5, 0.5));;
}

test "t12" {
    assert (normalize_color_tuple(180, 80, 90) == (0.5, 0.8, 0.9));;
}

test "t13" {
    assert (normalize_color_tuple(0, 0, 0) == (0.0, 0.0, 0.0));;
}

test "t14" {
    assert (normalize_color_tuple(0, 100, 25) == (0.0, 1.0, 0.25));;
}

test "t15" {
    assert (normalize_color_tuple(360, 100, 100) == (1, 1, 1));;
}

test "t16" {
    assert (
        normalize_color_tuple(
            sorted([0, 360])[0], sorted([0, 100])[0], sorted([0, 100])[0]
        )
        == (0, 0, 0)
    );;
}

test "t17" {
    assert (normalize_color_tuple(180, 0, 100) == (0.5, 0, 1));;
}

test "t18" {
    assert (normalize_color_tuple(180, 0, 0) == (0.5, 0, 0));;
}

test "t19" {
    assert (normalize_color_tuple(0, 100, 50) == (0, 1, 0.5));;
}

test "t20" {
    assert (
        normalize_color_tuple(100, 200, 300) == ((100 / 360), (200 / 100), (300 / 100))
    );;
}

test "t21" {
    assert (normalize_color_tuple(360, 100, 100) == (1.0, 1.0, 1.0));;
}

test "t22" {
    assert (normalize_color_tuple(0, 20, 40) == (0.0, 0.2, 0.4));;
}

test "t23" {
    assert (normalize_color_tuple(0, 0, 100) == (0, 0, 1));;
}

test "t24" {
    assert (normalize_color_tuple(0, 0, 0) == (0, 0, 0));;
}

test "t25" {
    assert (normalize_color_tuple(360, 0, 0) == (1, 0, 0));;
}

test "t26" {
    assert (normalize_color_tuple(360, 0, 100) == (1, 0, 1));;
}
